from build123d import *

outer_size = 80.0
wall_thickness = 5.0
hole_diameter = 28.0
counterbore_diameter = 40.0
counterbore_depth = 10.0
chamfer_distance = 8.0

solid_body = Box(outer_size, outer_size, outer_size)
solid_body = chamfer(solid_body.edges(), chamfer_distance)

hole_r = hole_diameter / 2
cbore_r = counterbore_diameter / 2
half_size = outer_size / 2

for axis in ['X', 'Y', 'Z']:
    for sign in [1, -1]:
        if axis == 'X':
            loc = Pos(sign * (half_size - counterbore_depth/2), 0, 0) * Rot(0, 90, 0)
        elif axis == 'Y':
            loc = Pos(0, sign * (half_size - counterbore_depth/2), 0) * Rot(90, 0, 0)
        else:
            loc = Pos(0, 0, sign * (half_size - counterbore_depth/2))
        solid_body = solid_body - loc * Cylinder(cbore_r, counterbore_depth)

for axis in ['X', 'Y', 'Z']:
    if axis == 'X':
        loc = Rot(0, 90, 0)
    elif axis == 'Y':
        loc = Rot(90, 0, 0)
    else:
        loc = None
    if loc:
        solid_body = solid_body - loc * Cylinder(hole_r, outer_size)
    else:
        solid_body = solid_body - Cylinder(hole_r, outer_size)

part = solid_body
part.name = "chamfered_box_with_counterbored_holes"
export_step(part, "output.step")
